// A dark tab with round ends from x0 to x1, h tall, centred on cy.
function statusPill(x0,cy,x1,h){
  var r=h/2;
  if(x1<x0+h) x1=x0+h;
  ctx.beginPath();
  ctx.arc(x0+r,cy,r,Math.PI*0.5,Math.PI*1.5);
  ctx.arc(x1-r,cy,r,-Math.PI*0.5,Math.PI*0.5);
  ctx.closePath(); ctx.fill();
}

